264	bool install_and_select_printer(Plater& plater, const std::string& vendor_id,
265	                                const std::string& model_id, const std::string& variant,
266	                                const std::string& default_filament, std::string& error)
267	{
268	    PresetBundle* presets = wxGetApp().preset_bundle;
269	    AppConfig* config = wxGetApp().app_config;
270	    if (!presets || !config || vendor_id.empty() || model_id.empty() || variant.empty()) {
271	        error = "Printer setup is unavailable because the preset system is not ready.";
272	        return false;
273	    }
274	    const auto old_vendors = config->vendors();
275	    const bool had_filaments = config->has_section(AppConfig::SECTION_FILAMENTS);
276	    const auto old_filaments = had_filaments ? config->get_section(AppConfig::SECTION_FILAMENTS)
277	                                             : std::map<std::string, std::string>();
278	    const std::string old_printer = presets->printers.get_selected_preset_name();
279	    auto rollback = [&]() -> std::string {
280	        config->set_vendors(old_vendors);
281	        config->set_section(AppConfig::SECTION_FILAMENTS, old_filaments);
282	        try {
283	            presets->load_presets(*config, ForwardCompatibilitySubstitutionRule::Enable,
284	                                  {std::string(), std::string(), std::string(), std::string()});
285	            if (!select_printer_preset(plater, old_printer))
286	                return "The previous printer preset could not be selected again.";
287	            if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
288	        } catch (const std::exception& exception) {
289	            return std::string("The previous preset configuration could not be reloaded: ") + exception.what();
290	        }
291	        return {};
292	    };
293	    try {
294	        std::map<std::string, std::map<std::string, std::set<std::string>>> vendors;
295	        vendors[vendor_id][model_id].insert(variant);
296	        std::map<std::string, std::string> filaments;
297	        if (!default_filament.empty()) filaments[default_filament] = "true";
298	        bool applied = false;
299	        bool selected = false;
300	        plater.update_objects_position_when_select_preset([&] {
301	            applied = presets->apply_vendor_config(vendors, filaments, config, false, model_id, variant,
302	                                                   default_filament);
303	            if (!applied) return;
304	            const Preset* preset = presets->printers.find_system_preset_by_model_and_variant(model_id, variant);
305	            Tab* tab = wxGetApp().get_tab(Preset::TYPE_PRINTER);
306	            if (!preset || !tab) return;
307	            tab->select_preset(preset->name);
308	            plater.on_config_change(presets->full_config());
309	            selected = true;
310	        });
311	        if (!applied) {
312	            const std::string rollback_error = rollback();
313	            error = rollback_error.empty()
314	                ? "The printer profile could not be installed. Your previous setup is unchanged."
315	                : "The printer profile could not be installed. " + rollback_error;
316	            return false;
317	        }
318	        if (!selected) {
319	            const std::string rollback_error = rollback();
320	            error = rollback_error.empty()
321	                ? "The installed profile could not be selected. Your previous setup is unchanged."
322	                : "The installed profile could not be selected. " + rollback_error;
323	            return false;
324	        }
325	        if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
326	        presets->export_selections(*config);
327	        return true;
328	    } catch (const std::exception& exception) {
329	        const std::string rollback_error = rollback();
330	        error = std::string("The printer profile could not be loaded: ") + exception.what();
331	        if (!rollback_error.empty()) error += " " + rollback_error;
332	        return false;
333	    }
334	}
